package dev.mineagent.runtime.core.task;
import com.fasterxml.jackson.databind.*;
import java.util.*;
public record GameCommandPlan(String summary,List<String> commands) {
    public GameCommandPlan {commands=List.copyOf(commands);if(summary==null||summary.length()>256||commands.isEmpty()||commands.size()>8||commands.stream().anyMatch(c->c==null||c.isBlank()||c.length()>2048||c.codePoints().anyMatch(Character::isISOControl)))throw new IllegalArgumentException("GAME_COMMAND_PLAN_INVALID");}
    public static GameCommandPlan parse(String text)throws Exception{if(text==null||text.length()>24000)throw new IllegalArgumentException("GAME_COMMAND_PLAN_SIZE");text=text.strip();if(text.startsWith("```")){int i=text.indexOf('\n');if(i<0||!text.endsWith("```"))throw new IllegalArgumentException("GAME_COMMAND_PLAN_JSON");text=text.substring(i+1,text.length()-3).strip();}var json=new ObjectMapper().enable(DeserializationFeature.FAIL_ON_TRAILING_TOKENS).enable(com.fasterxml.jackson.core.JsonParser.Feature.STRICT_DUPLICATE_DETECTION);var n=json.readTree(text);if(n==null||!n.isObject()||n.size()!=2||!n.path("summary").isTextual()||!n.path("commands").isArray())throw new IllegalArgumentException("GAME_COMMAND_PLAN_JSON");var values=new ArrayList<String>();for(var c:n.path("commands")){if(!c.isTextual())throw new IllegalArgumentException("GAME_COMMAND_PLAN_JSON");String command=c.textValue().strip();if(command.startsWith("/"))command=command.substring(1);values.add(command);}return new GameCommandPlan(n.path("summary").asText(),values);}
    public static String instructions(){return "你是 Minecraft 26.1.2 玩家指令助手。只返回严格 JSON {\"summary\":\"中文说明\",\"commands\":[\"不带斜杠的游戏指令\"]}。最多8条，每条最多2048字。使用当前玩家可执行的真实游戏指令，不是操作系统shell，不调用 /ai 子命令，不自动提权。支持 gamerule/scoreboard/give/item/enchant 及其它实际允许的原生或Mod指令。只针对玩家明确要求，不扩展目标。需要新注册物品ID时不要伪造已有ID，改为说明应使用内容生成的BOOT_EXTENSION；give自定义组件是新ItemStack不是新registry entry。以提供的真实命令usage为准，不用旧版本规则名。执行之前用户会看到命令并确认。";}
}
